python -c "
import sys, json, re, os
try:
    data = json.load(sys.stdin)
    fp = (data.get('tool_input') or {}).get('file_path', '')
    fp_norm = fp.replace('\\\\', '/')
    fname = os.path.basename(fp_norm)
    msg = None
    if fname == '.env':
        msg = 'ROSETTA: escritura en .env bloqueada. Los secretos de API nunca van al repositorio.'
    elif fname == 'workspace.json' and '.obsidian' in fp_norm:
        msg = 'ROSETTA: workspace.json de Obsidian es config local del usuario y no debe modificarse ni commitearse.'
    elif re.search(r'\\bcorpus\\b.*\\.pdf$', fp_norm, re.IGNORECASE):
        msg = 'ROSETTA: Los PDFs del corpus son solo lectura. Colocalos manualmente en corpus/<marco>/.'
    if msg:
        print(json.dumps({'continue': False, 'stopReason': msg}))
except Exception:
    pass
" 2>/dev/null || true
